package com.bernaferrari.sdkmonitor.ui.icons

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.graphics.vector.group
import androidx.compose.ui.unit.dp

/**
 * SDK Monitor's mark: "SDK" in six wavy bands, red to yellow, as in the launcher icon
 * (store-listing/brand/foreground.svg; the letters clip the bands). It keeps its own colors.
 */
val SdkMonitorMark: ImageVector
    get() {
        _sdkMonitorMark?.let { return it }
        return ImageVector
            .Builder(name = "SdkMonitorMark", defaultWidth = 44.dp, defaultHeight = 18.dp, viewportWidth = 44f, viewportHeight = 18f)
            .apply {
                group(translationX = -32.25f, translationY = -45f, clipPathData = addPathNodes(LETTERS)) {
                    BANDS.forEach { (argb, d) -> addPath(pathData = addPathNodes(d), fill = SolidColor(Color(argb))) }
                }
            }.build()
            .also { _sdkMonitorMark = it }
    }

private var _sdkMonitorMark: ImageVector? = null

